-- Phase 1 additive wardrobe foundation. Keep original category and profile mannequin_preference.
alter table public.wardrobe_items add column if not exists category_group text, add column if not exists formality text, add column if not exists season text, add column if not exists dominant_color_hex text, add column if not exists color_family text, add column if not exists is_clean boolean not null default true, add column if not exists wear_count integer not null default 0, add column if not exists last_worn_date date;
update public.wardrobe_items set category_group=case when lower(category) in ('shirt','t_shirt','kurta','dress','top') then 'top' when lower(category) in ('trousers','jeans','skirt','shorts','bottom') then 'bottom' when lower(category) in ('footwear','shoes','shoe') then 'shoes' when lower(category) in ('jacket','blazer','coat','outerwear') then 'outerwear' else 'accessory' end where category_group is null;
alter table public.wardrobe_items add constraint wardrobe_items_category_group_check check(category_group is null or category_group in ('top','bottom','shoes','outerwear','accessory')), add constraint wardrobe_items_formality_check check(formality is null or formality in ('casual','formal','sport')), add constraint wardrobe_items_color_family_check check(color_family is null or color_family in ('neutral','warm','cool','bold','pastel')), add constraint wardrobe_items_wear_count_check check(wear_count>=0);
create table if not exists public.tryon_renders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,clothing_item_id uuid not null references public.wardrobe_items(id) on delete cascade,pose text not null check(pose in ('male_front','male_back','female_front','female_back')),render_url text not null,created_at timestamptz not null default now(),unique(user_id,clothing_item_id,pose));
create table if not exists public.outfit_plans(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,start_date date not null,end_date date not null,status text not null default 'draft',created_at timestamptz not null default now(),check(end_date>=start_date));
create table if not exists public.outfit_plan_days(id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.outfit_plans(id) on delete cascade,date date not null,top_id uuid references public.wardrobe_items(id) on delete set null,bottom_id uuid references public.wardrobe_items(id) on delete set null,shoe_id uuid references public.wardrobe_items(id) on delete set null,ai_note text,feedback smallint,created_at timestamptz not null default now(),check(feedback is null or feedback in (-1,0,1)),unique(plan_id,date));
alter table public.tryon_renders enable row level security; alter table public.outfit_plans enable row level security; alter table public.outfit_plan_days enable row level security;
create policy "Users manage own tryon renders" on public.tryon_renders for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Users manage own outfit plans" on public.outfit_plans for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Users manage days in own outfit plans" on public.outfit_plan_days for all to authenticated using(exists(select 1 from public.outfit_plans p where p.id=plan_id and p.user_id=auth.uid())) with check(exists(select 1 from public.outfit_plans p where p.id=plan_id and p.user_id=auth.uid()));
create index if not exists wardrobe_items_user_category_group_idx on public.wardrobe_items(user_id,category_group); create index if not exists wardrobe_items_user_color_family_idx on public.wardrobe_items(user_id,color_family); create index if not exists wardrobe_items_user_formality_idx on public.wardrobe_items(user_id,formality);
